using System.Text.RegularExpressions;

string muster = @"^[1-5][A-E]HIF$";
string[] eingaben =
    { "2AHIF", "2ahif", "6AHIF", "2AHIFX" };

foreach (string k in eingaben)
{
    bool streng = Regex.IsMatch(k, muster);
    bool locker = Regex.IsMatch(k, muster,
        RegexOptions.IgnoreCase);
    Console.WriteLine(
        $"{k}: {streng} {locker}");
}
// Ausgabe:
// 2AHIF: True True
// 2ahif: False True
// 6AHIF: False False
// 2AHIFX: False False

using System.Text.RegularExpressions;

string text = "Test am 14.03.2026 in B3";
Match m = Regex.Match(text,
    @"(\d{2})\.(\d{2})\.(\d{4})");

if (m.Success)
{
    Console.WriteLine(m.Value);
    Console.WriteLine(m.Index);
    string monat = m.Groups[2].Value;
    Console.WriteLine($"Monat: {monat}");
}
// Ausgabe:
// 14.03.2026
// 8
// Monat: 03

using System.Text.RegularExpressions;

string liste = "Max:2 Lena:1 Ali:4";
string muster =
    @"(?<name>\w+):(?<note>[1-5])";

foreach (Match m in
         Regex.Matches(liste, muster))
{
    string n = m.Groups["name"].Value;
    string note = m.Groups["note"].Value;
    Console.WriteLine($"{n} hat {note}");
}
// Ausgabe:
// Max hat 2
// Lena hat 1
// Ali hat 4

using System.Text.RegularExpressions;

string d = "Abgabe: 14.03.2026";
string iso = Regex.Replace(d,
    @"(\d{2})\.(\d{2})\.(\d{4})",
    "$3-$2-$1");
Console.WriteLine(iso);

string s = "Hallo    Welt  !";
Console.WriteLine(
    Regex.Replace(s, @"\s+", " "));
// Ausgabe:
// Abgabe: 2026-03-14
// Hallo Welt !

